{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyPLLDMO04mY4Q08lJB3A9mX"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":1,"metadata":{"colab":{"base_uri":"https://localhost:8080/","height":254},"id":"czOWEZPINUfY","executionInfo":{"status":"ok","timestamp":1782918427933,"user_tz":-330,"elapsed":5335,"user":{"displayName":"D Girl","userId":"10979297630896453060"}},"outputId":"72aa7a14-4518-4044-b4f0-5618a8d636de"},"outputs":[{"output_type":"display_data","data":{"text/plain":["<Figure size 1500x600 with 2 Axes>"],"image/png":"\n"},"metadata":{}}],"source":["import pandas as pd\n","import folium\n","from folium.plugins import HeatMap, MarkerCluster\n","from sklearn.cluster import KMeans\n","import matplotlib.pyplot as plt\n","\n","# Load & clean\n","df = pd.read_csv('/content/Dataset .csv')\n","df = df[(df['Latitude'] != 0) & (df['Longitude'] != 0)]\n","df = df[(df['Latitude'].between(-90,90)) & (df['Longitude'].between(-180,180))].copy()\n","\n","# ── 1. Interactive Folium Map ──────────────────────────────\n","m = folium.Map(location=[27.5, 77.0], zoom_start=4, tiles='CartoDB positron')\n","\n","HeatMap(df[['Latitude','Longitude']].values.tolist(),\n","        radius=8, blur=10, min_opacity=0.4).add_to(m)\n","\n","mc = MarkerCluster(name='Restaurants').add_to(m)\n","\n","def rating_color(r):\n","    if r >= 4: return 'green'\n","    elif r >= 3: return 'blue'\n","    elif r >= 2: return 'orange'\n","    else: return 'red'\n","\n","for _, row in df.sample(1500, random_state=42).iterrows():\n","    folium.CircleMarker(\n","        location=[row['Latitude'], row['Longitude']],\n","        radius=4, color=rating_color(row['Aggregate rating']),\n","        fill=True, fill_opacity=0.7,\n","        popup=folium.Popup(\n","            f\"<b>{row['Restaurant Name']}</b><br>\"\n","            f\"City: {row['City']}<br>Cuisines: {row['Cuisines']}<br>\"\n","            f\"Rating: {row['Aggregate rating']}\", max_width=220)\n","    ).add_to(mc)\n","\n","folium.LayerControl().add_to(m)\n","m.save('restaurant_map.html')\n","\n","# ── 2. KMeans Cluster Plot ─────────────────────────────────\n","kmeans = KMeans(n_clusters=6, random_state=42, n_init=10)\n","df['Cluster'] = kmeans.fit_predict(df[['Latitude','Longitude']])\n","\n","cluster_labels = {\n","    0: 'South Asia (India)', 1: 'North America',\n","    2: 'Oceania/NZ',         3: 'Europe',\n","    4: 'Africa',             5: 'South America'\n","}\n","colors = ['#e63946','#2a9d8f','#e9c46a','#457b9d','#f4a261','#8338ec']\n","cluster_sizes = df['Cluster'].value_counts().sort_index()\n","\n","fig, axes = plt.subplots(1, 2, figsize=(15, 6))\n","fig.suptitle('Geographic Distribution of Restaurants', fontsize=15, fontweight='bold')\n","\n","for c in range(6):\n","    sub = df[df['Cluster'] == c]\n","    axes[0].scatter(sub['Longitude'], sub['Latitude'], s=3, alpha=0.4,\n","                    color=colors[c], label=f\"{cluster_labels[c]} ({len(sub):,})\")\n","axes[0].set_title('Restaurant Locations by Cluster')\n","axes[0].set_xlabel('Longitude'); axes[0].set_ylabel('Latitude')\n","axes[0].legend(loc='lower left', fontsize=8, markerscale=3)\n","\n","bar_labels = [f\"{cluster_labels[i]}\\n({cluster_sizes[i]:,})\" for i in range(6)]\n","axes[1].barh(bar_labels[::-1], [cluster_sizes[i] for i in range(6)][::-1],\n","             color=colors[::-1], edgecolor='white')\n","axes[1].set_title('Restaurant Count by Geographic Cluster')\n","axes[1].set_xlabel('Number of Restaurants')\n","\n","plt.tight_layout()\n","plt.savefig('restaurant_clusters.png', dpi=150)\n","plt.show()"]}]}